def test_contour_no_valid_data(algorithm, method, masked, levels):
    # Invalid data must not result in NaN levels reaching the contour generator.
    z = (np.ma.array(np.ones((2, 2)), mask=True) if masked
         else np.full((2, 2), np.nan))
    fig, ax = plt.subplots()
    cs = getattr(ax, method)(z, algorithm=algorithm, levels=levels)

    assert len(cs.levels) > 0
    assert np.isfinite(cs.levels).all()
    assert (np.diff(cs.levels) > 0).all()
    if levels is not None:
        assert cs.levels.tolist() == levels
    assert all(not collection.get_paths() for collection in cs.collections)
